onReportHover(payload) {
  const inner = this.$refs.screenRoot && this.$refs.screenRoot.querySelector('.screen-inner')
  if (!inner || !payload) return
  const box = inner.getBoundingClientRect()
  const scale = box.height / DESIGN_H || 1
  const top = (payload.top - box.top) / scale
  this.cancelHideDetail()
  const item = payload.item || {}
  this.reportHover = { item, top: Math.max(80, Math.min(DESIGN_H - 420, top)) }
  // /patrol/realtime 的 items 只含异常项，按 inspectionId 补拉全量检查项（含填报值为“无”的项）
  this.loadDetailItems(item)
},
loadDetailItems(item) {
  const inspectionId = item && item.inspectionId
  if (!inspectionId) return
  const seq = ++this.detailFetchSeq
  // request 拦截器成功时 res 为后端 data 或完整 body，统一取 items；失败保留异常项占位
  Promise.resolve(getInspection(inspectionId))
    .then((res) => {
      if (seq !== this.detailFetchSeq) return
      if (!this.reportHover || String((this.reportHover.item || {}).inspectionId || '') !== String(inspectionId)) return
      const data = res && (res.data !== undefined ? res.data : res)
      const rows = data && Array.isArray(data.items) ? data.items : []
      if (!rows.length) return
      const items = rows.map((it) => ({
        label: it.checkContent || it.checkTypeName || '',
        value: it.fillValue == null || it.fillValue === '' ? '无' : String(it.fillValue)
      }))
      this.$set(this.reportHover, 'item', Object.assign({}, this.reportHover.item, { items }))
    })
    .catch(() => {})
},

cancelHideDetail() {
  if (this.hideDetailTimer) { clearTimeout(this.hideDetailTimer); this.hideDetailTimer = null }
},
hideDetail() {
  this.detailFetchSeq++
  this.reportHover = null
},
